<template><section><div class="toolbar"><p>原采购累计实收保留，退仓出库、拒收收回与净入库分别核对。退供单审核后锁定原批次，仓库实际出库后扣账。</p><el-button v-hasPermi="['warehouse:purchaseReturn:create']" size="small" type="primary" @click="$router.push({path:'/oms-supplychain/purchaseReturns',query:{purchaseId:purchaseId,create:'1'}})">创建采购退仓</el-button></div><el-alert v-if="error" title="采购退仓记录加载失败，请刷新重试" type="error" :closable="false"/><el-table :data="netLines" size="small"><el-table-column prop="skuSn" label="SKU" min-width="240"/><el-table-column label="原采购入账 / 退仓出库 / 拒收收回 / 净入库" min-width="250"><template slot-scope="{row}">{{row.postedQuantity}} / {{row.returned}} / {{row.recovered}} / {{Number(row.postedQuantity)-row.returned+row.recovered}} {{row.stockUnit}}</template></el-table-column></el-table><el-table :data="rows" v-loading="loading" size="small"><el-table-column label="退仓单" min-width="250"><template slot-scope="{row}"><router-link :to="{path:'/oms-supplychain/purchaseReturns',query:{id:row.id}}">{{row.return_sn}}</router-link></template></el-table-column><el-table-column prop="supplier_name" label="供应商" min-width="150"/><el-table-column label="申请 / 实出 / 已扣账" min-width="160"><template slot-scope="{row}">{{row.quantity}} / {{row.accepted_quantity}} / {{row.posted_quantity}}</template></el-table-column><el-table-column label="业务结果" min-width="160"><template slot-scope="{row}">{{row.progress_label||states[row.state]||row.state}}</template></el-table-column><el-table-column prop="last_error" label="待处理原因" min-width="220"/></el-table></section></template>
<script>
import {listReturns} from '@/api/purchase/returns'
export default{props:{purchaseId:{type:Number,required:true},originalLines:{type:Array,default:()=>[]}},data:()=>({rows:[],returned:[],recovered:[],loading:false,error:false,sequence:0,states:{DRAFT:'待审核',APPROVING:'库存锁定中',APPROVED:'退仓执行中',CANCELING:'停止剩余退仓待确认',CANCELED:'已取消或截停',COMPLETED:'全部出库扣账',ATTENTION:'待核对'}}),computed:{netLines(){return this.originalLines.map(l=>({...l,returned:Number((this.returned.find(r=>r.sku_sn===l.skuSn&&r.stock_unit===l.stockUnit)||{}).quantity||0),recovered:Number((this.recovered.find(r=>r.sku_sn===l.skuSn&&r.stock_unit===l.stockUnit)||{}).quantity||0)}))}},watch:{purchaseId:{immediate:true,handler(){this.load()}}},beforeDestroy(){this.sequence++},methods:{async load(){const seq=++this.sequence;this.loading=true;this.error=false;try{const r=await listReturns({purchase_id:this.purchaseId,pageSize:100});if(seq===this.sequence){this.rows=r.data.rows||[];this.returned=r.data.returned_by_sku||[];this.recovered=r.data.recovered_by_sku||[]}}catch(_){if(seq===this.sequence)this.error=true}finally{if(seq===this.sequence)this.loading=false}}}}
</script>
<style scoped>.toolbar{display:flex;gap:16px;align-items:center;justify-content:space-between;font-size:13px;color:#7a899d;margin:16px 0}</style>
